private string ResolveTemplateCode(string specialBranchId)
{
    if (specialBranchId == "A1" || specialBranchId == "A0")
        return "2";
    return "1"; // BCK(là hạng B), C1 và các hạng khác
}

private void BindTemplateNote()
{
    pnlTemplateNote.Visible = true;

    if (this.TemplateCode == "2")
    {
        lblTemplateMau.Text = "Mẫu 2";
        lblTemplateName.Text = "Văn bằng tốt nghiệp — hạng A1, A0";
    }
    else
    {
        lblTemplateMau.Text = "Mẫu 1";
        lblTemplateName.Text = "Văn bằng tốt nghiệp — hạng B, C1";
    }
}

