private void LoadData()
{
    // Nhớ lại niên kỳ khi tìm kiếm (để xuất dữ liệu và ký số ko bị lệch so với ds đang nhìn thấy)
    this.YearID = WebGlobal.ToInt32(ddlYearID.SelectedValue);
    this.ExamDateID = WebGlobal.ValueFromDropBoxListInt32(ddlExamDateID);

    // tiêu đề report (nhớ lại kỳ thi hoặc tên năm học)
    if (ddlExamDateID.SelectedIndex > 0)
        this.ExamDateTitlte = ddlExamDateID.SelectedItem.Text;
    else if (ddlYearID.SelectedIndex > 0)
        this.ExamDateTitlte = ddlYearID.SelectedItem.Text;


    #region  Nạp dữ liệu kí số trước khi binding để kiểm tra trạng thái edit trong lưới (nếu có)

    LoadSignCA();

    //if (uSignArea.IsLockingDoc)
    //{
    //    bolIsLockingDoc = true;
    //    strLocked = "<span style='color:Purple'> (ĐÃ KHOÁ - DO KÝ SỐ) </span>";
    //}

    // Lưu cờ nhận biết trạng thái lock lúc LoadData --> trước khi save thấy cờ thay đổi --> yêu cầu nạp lại data
    //this.IsLockingDoc = uSignArea.IsLockingDoc;

    #endregion

    // Tải dữ liệu (nhớ luôn data để khi xuất hoặc ký số ko cần nạp lại)
    SimsObject.SIM_Area obj = new SimsObject.SIM_Area();
    this.dtbData = obj.GetDataTable("WEB_GraduationCerList_Search",
        "@YearID", this.YearID,
        "@ExamDateID", this.ExamDateID);

    if (dtbData != null)
    {
        if (dtbData.Rows.Count == 0)
            this.TemplateCode = "1";
        else
            this.TemplateCode = ResolveTemplateCode(dtbData.Rows[0]["SpecialBranchID"].ToString());

        // debug local: ?templatecode=1 hoặc 2
        if (Request.Url.DnsSafeHost == "localhost" && Request["templatecode"] != null)
            this.TemplateCode = Request["templatecode"].ToString();

        BindTemplateNote();
        LoadSignCA_Multi();

        gvData.DataSource = dtbData;
        gvData.DataBind();
        udpContent.Update();
    }
    else
    {
        MsgBox.ShowError("Việc tải thông tin bị lỗi!");
    }
}

