private void LoadData()
{
    bool bolSearchByClass = ddlClassID.SelectedIndex > 0;

    this.ClassID = bolSearchByClass ? ddlClassID.SelectedValue : null;
    this.ClassTitle = bolSearchByClass ? ddlClassID.SelectedItem.Text : null;
    this.TemplateCode = bolSearchByClass ? "2" : "1";

    // Nhớ lại niên kỳ khi tìm kiếm (để xuất dữ liệu và ký số ko bị lệch so với ds đang nhìn thấy)
    this.YearID = WebGlobal.ToInt32(ddlYearID.SelectedValue);
    this.ExamDateID = WebGlobal.ValueFromDropBoxListInt32(ddlExamDateID);

    if (bolSearchByClass)
        this.ExamDateTitlte = this.ClassTitle;
    else if (ddlExamDateID.SelectedIndex > 0)
        this.ExamDateTitlte = ddlExamDateID.SelectedItem.Text;
    else if (ddlYearID.SelectedIndex > 0)
        this.ExamDateTitlte = ddlYearID.SelectedItem.Text;

    #region  Nạp dữ liệu kí số trước khi binding để kiểm tra trạng thái edit trong lưới (nếu có)

    LoadSignCA();

    #endregion

    SimsObject.SIM_Area obj = new SimsObject.SIM_Area();
    if (bolSearchByClass)
    {
        this.dtbData = obj.GetDataTable("WEB_GraduationXacNhanHoanThanh_Search",
            "@ClassID", this.ClassID);
    }
    else
    {
        this.dtbData = obj.GetDataTable("WEB_GraduationCerList_Search",
            "@YearID", this.YearID,
            "@ExamDateID", this.ExamDateID);
    }

    if (dtbData != null)
    {
        BindTemplateNote();
        LoadSignCA_Multi();

        gvData.DataSource = dtbData;
        gvData.DataBind();
        udpContent.Update();
    }
    else
    {
        MsgBox.ShowError("Việc tải thông tin bị lỗi!");
    }
}

